import {POST_QUEST_STEPS,POST_QUEST_ENDINGS,POST_QUEST_GOLD,postQuestProgress} from './expedition-post-quest.mjs';
import {EXPEDITIONS,GEAR,HEROES} from './expedition-data.mjs';
import {equipmentStats} from './expedition-equipment-view.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function postQuestView(g){const p=postQuestProgress(g),q=g.postQuest,last=g.history[0],failed=Boolean(q?.selected&&last?.route===q.selected&&!last.won&&last.id>=q.startedAt);return `<section class="guild-panel post-quest" data-guild-pane="journey" data-story-book="postquest" id="post-quest"><p class=eyebrow>单人分支任务 / 归信航程</p><h2>这一封，写上真正走过的路。</h2><p>接取后依次选择岸路、渡海接应，再把信送过沉船邮路。前两段各有两条路线，只需走所选的一条；地图上的所有路线仍可自由探索。</p><p class=story-progress role=status>${p.started?'路签 '+p.completed+'/3 · 第'+q.startedAt+'次远征起接取 · ':''}${esc(p.reason)}</p>${!p.started?`<button data-postquest-start ${p.canStart?'':'disabled'}>接取归信航程</button>`:''}<div class=post-quest-steps>${POST_QUEST_STEPS.map((s,i)=>{const r=q?.steps[i],current=p.started&&p.completed===i&&!p.ending;return `<article data-postquest-stage="${i}"><p class=eyebrow>第${i+1}段 · ${r?'已完成':current?'当前路段':'尚待抵达'}</p><h3>${s.title}</h3><p>${esc(r?s.after:s.before)}</p>${r?`<p class=post-quest-proof>实际通路：${EXPEDITIONS[r.route].name} · 第${r.id}次正式通关已领取${r.command?' · 当时本人 '+esc(HEROES.find(h=>h.id===r.command.heroId).name):''}。</p>`:`<div class=post-quest-routes>${s.routes.map(v=>`<article data-postquest-route="${v.route}"><h4>${EXPEDITIONS[v.route].name}${current&&p.selected===v.route?' · 已选择':''}</h4><p>${v.text}</p>${current?`<button data-postquest-path="${v.route}" ${g.pending||p.selected===v.route?'disabled':''}>${p.selected===v.route?'已选此通路':'选择此通路'}</button>`:''}</article>`).join('')}</div>`}${current&&p.selected?`<p>本段只等待${EXPEDITIONS[p.selected].name}的正常通关结算，其他路线与失败均不清空进度。</p>${failed?`<p class=post-quest-failed>第${last.id}次通过${last.cleared}房后止步，本段尚未取得路签；已领取的普通收益保留。</p><button data-cycle-action="retry" data-cycle-value="${last.id}">载入本次止步方案再调整</button>`:''}<button data-postquest-prepare ${g.pending?'disabled':''}>准备所选通路 · ${EXPEDITIONS[p.selected].name}</button>`:''}</article>`;}).join('')}</div><h3>回信抵岸后，留下一种回答</h3><p>三段全部完成后，亲自选择一次交付：${POST_QUEST_GOLD}金币与一件已有遗物进入仓库，再手动分配；不额外发经验。前段路签不提供战斗加成、折扣或补给。</p><div class=post-quest-endings>${Object.entries(POST_QUEST_ENDINGS).map(([id,e])=>`<article data-postquest-ending="${id}"><h4>${e.name}</h4><p>${e.text}</p><p>${GEAR[e.gear].name} · ${POST_QUEST_GOLD}金币</p><small>${esc(equipmentStats(e.gear))}</small>${p.ending===id?'<p class=post-quest-delivered>已选择并交付，奖励已入仓。</p><button data-guild-tab=equipment>去仓库分配</button>':!p.ending?`<button data-postquest-deliver="${id}" ${p.canClaim?'':'disabled'}>选择此交付 · ${GEAR[e.gear].name}</button>`:'<p>本次未选的回答，不再发放奖励。</p>'}</article>`).join('')}</div><p>实验、试演、历史或收藏回看都不能取得路签。未领取的通关不推进；任务与战利品随公会和整档备份保留。已完成段落不可改写，当前未完成通路可在没有待领取远征时改选。</p></section>`;}
